        instance_match = re.search(r'Instance:\s*(.+)', instance_part)
        if not instance_match:
            continue

        instance = instance_match.group(1).strip()

        item_index = i + 2
        if item_index < len(result['rows']):
            label = result['rows'][item_index]['value']
        else:
            label = 'unknown'

        user_data[user_id].append((date_match.group(1).strip(), instance, label))

